function ECSWorld:Initial(isClient)
    self.isClient = isClient
    xTry(function()
        self:InitSystem()
        if self.isClient then
            self:InitRecordSystem()
        end
        self:InitGroup()
        self:GameStart()

    end, function()
        printError("%s", debug.traceback());
    end)
end

function ECSWorld:LazyExecuteEntityOperation()
    for i = 1, #self.destroyEntityCache do
        self:RemoveEntity(self.destroyEntityCache[i])
    end
    self.destroyEntityCache = {}
end

---RemoveEntity 移除实体
---@param entity table
function ECSWorld:RemoveEntity(entity)
    if self.isRecalc then
        self:RecalcDestroyEntity(entity)
    else
        self:DestroyEntityAndDispatch(entity)
        self:RecordEntityDestroy(entity)
    end
end

---DestroyEntityAndDispatch
---@param entity table
function ECSWorld:DestroyEntityAndDispatch(entity)
    --将要释放的事件s
    self:DispatchEntityOptimizeWillBeDestroyed(entity)
    self:DestroyEntityNoDispatch(entity)
    -- 释放事件
    self:DispatchOptimizeDestroy(entity)
end

function ECSWorld:DestroyEntityNoDispatch(entity)
    self:DispatchWillBeDestroy(entity)
    local id = entity:ID()
    table.map(self.entities, function(key, value)
        if value:ID() == id then
            return nil
        else
            return value
        end
    end)
    self.entitiesDict[tostring(id)] = nil
    entity:Delete()
    self.groupMgr:OnEntityDestroy(entity)
    self:DispatchDestroy(entity)
end

function ECSWorld:DestroyEntityImmediately(id)
    local entity = self:GetEntity(id)
    self:DestroyEntityAndDispatch(entity)
end

function ECSWorld:DispatchEntityOptimizeWillBeDestroyed(entity)
    Events.Broadcast(ECSWorld.events.OnEntityOptimizeWillBeDestroyed, entity)
end

function ECSWorld:DispatchOptimizeDestroy(entity)
    Events.Broadcast(ECSWorld.events.OnEntityOptimizeDestroyed, entity)
end

function ECSWorld:DispatchWillBeDestroy(entity)
    Events.Broadcast(ECSWorld.events.OnEntityWillBeDestroyed, entity)
end

function ECSWorld:DispatchDestroy(entity)
    Events.Broadcast(ECSWorld.events.OnEntityDestroyed, entity)
end

