end

local function ConstructComp(compName)
    local component = require(string.format("Game.Logic.%s", compName))
    component = component.New()
    return component
end

function ECSWorld:InitSystem()
    local systemNames = self:GetSystemNames()
    if isNull(systemNames) then
        return
    end
    table.walk(systemNames, function (key,value)
        local system = ConstructComp(value)
        if not isNull(system) then
            system.world = self
            table.insert(self.systems,system)
            system:Initial() -- system初始化
        end
    end)
end

function ECSWorld:InitRecordSystem()

end

function ECSWorld:InitGroup()
    self.groupMgr = import("Frame.ECS.ECSGroupManager").New(self)
end

function ECSWorld:GameStart()
    local len = table.length(self.systems)

    if len > 0 then
        for i = 1, len do
            self.systems[i]:OnSystemStart()
        end
    end
end

function ECSWorld:Dispose()
    print(string.format("world dispose entity count %d", table.count(self.entities or {})))
    for i, entity in pairs(self.entities or {}) do
        self:DestroyEntityAndDispatch(entity)
    end
    for i = 1, table.count(self.destroyEntityCache or {}) do
        self:DispatchEntityOptimizeWillBeDestroyed(self.destroyEntityCache[i]);
        self:DispatchOptimizeDestroy(self.destroyEntityCache[i]);
    end
    self.destroyEntityCache = {}
    self.entities = {}
    self.entitiesDict = {}
    for i = 1, table.length(self.systems) do
        self.systems[i]:Dispose()
    end
    self.systems = {}

end

function ECSWorld:RenderLoop(deltaTime)
    if self.isStart then
        self:BeforeRenderUpdate(deltaTime)
        self:RenderUpdate(deltaTime)
    end
end

