---GetEntity 获取实体
---@param id table
function ECSWorld:GetEntity(id)
    return self.entitiesDict[checkString(id)]
end

---HasEntity 是否存在实体
---@param id table
function ECSWorld:HasEntity(id)
    return isSet(self.entitiesDict,checkString(id))
end

---GetEntityList 根据组件得到实体
---@param components table
function ECSWorld:GetEntityList(components)
    local tuple = {}
    local len = table.length(self.entities)
    if len > 0 then
        for i = 1, len do
            if self:GetAllExistComp(components,self.entities[i]) then
                table.insert(tuple,self.entities[i])
            end
        end
    end
    return tuple
end

function ECSWorld:GetAllExistComp(components, entity)
    for i = 1, #components do
        if not entity:IsCompExistsByName(components[i]) then
            return false
        end
    end
    return true
end

function ECSWorld:CreateEntity(name,id)
    if isSet(self.entitiesDict, checkString(id)) then
        printError("Create Entity ID has Exists --> %d <--", checkNumber(id))
        return
    end

    local entity = self:NewEntity(name, id)
    self:AddEntity(entity)
    return entity
end

function ECSWorld:NewEntity(name, id)
    local entity = import('Frame.ECS.ECSEntity').New(self)
    entity:ID(id)
    entity.name = name
    entity:CreateFrame(self.frameCount)
    return entity
end

function ECSWorld:AddEntity(entity)
    self:CreateEntityNoDispatch(entity)
    self:DispatchOptimizeCreate(entity)
    --self:RecordEntityCreate(entity)  记录类型暂时不要
end

function ECSWorld:DispatchOptimizeCreate(entity)
    Events.Broadcast(ECSWorld.events.OnEntityOptimizeCreated, entity)
end

function ECSWorld:CreateEntityNoDispatch(entity)
    if (isSet(self.entitiesDict, tostring(entity:ID()))) then
        printError("CreateEntityNoDispatch 创建实体 id [%d] 冲突", entity.ID())
    end
    table.insert(self.entities, entity)
    self.entitiesDict[tostring(entity:ID())] = entity
    Events.Broadcast(ECSWorld.events.OnEntityCreated, entity)
end
return ECSWorld